<template>
  <div class="admin-page">
    <header class="admin-header">
      <div><p>系统管理</p><h1>云笺管理后台</h1><span>管理用户、问题反馈和平台运行状态</span></div>
      <button class="btn btn-secondary" type="button" :disabled="loading" @click="loadCurrent"><RefreshCw :size="16" :class="{spin:loading}" />刷新</button>
    </header>
    <nav class="admin-tabs" aria-label="管理模块">
      <button v-for="item in tabs" :key="item.key" :class="{active:tab===item.key}" type="button" @click="selectTab(item.key)"><component :is="item.icon" :size="16" />{{item.label}}</button>
    </nav>

    <main class="admin-content">
      <section v-if="tab==='overview'" class="overview-grid">
        <article v-for="item in overviewItems" :key="item.key"><component :is="item.icon" :size="20" /><div><strong>{{formatNumber(overview[item.key]||0,item.bytes)}}</strong><span>{{item.label}}</span></div></article>
      </section>

      <section v-else-if="tab==='users'" class="admin-section">
        <div class="section-toolbar"><div><h2>用户管理</h2><p>封禁账号会立即退出该用户的全部登录设备。</p></div><div class="toolbar-filters"><input v-model.trim="userFilters.q" class="input" placeholder="用户名、昵称或邮箱" @keydown.enter="loadUsers"/><select v-model="userFilters.status" class="input" @change="loadUsers"><option value="">全部状态</option><option value="1">正常</option><option value="0">已封禁</option></select><select v-model="userFilters.role" class="input" @change="loadUsers"><option value="">全部角色</option><option value="USER">普通用户</option><option value="ADMIN">管理员</option></select><button class="btn btn-primary" type="button" @click="loadUsers"><Search :size="15"/>查询</button></div></div>
        <div class="data-table-wrap"><table class="data-table"><thead><tr><th>用户</th><th>角色</th><th>账号状态</th><th>最近登录</th><th>注册时间</th><th>操作</th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td><div class="user-cell"><span>{{(user.nickname||user.username).charAt(0).toUpperCase()}}</span><div><strong>{{user.nickname||user.username}}</strong><small>@{{user.username}} · {{user.email||'未填写邮箱'}}</small></div></div></td><td><select :value="user.systemRole||'USER'" :disabled="user.id===currentUserId" @change="changeRole(user,$event.target.value)"><option value="USER">普通用户</option><option value="ADMIN">管理员</option></select></td><td><span :class="['status-pill',user.status===1?'ok':'danger']">{{user.status===1?'正常':'已封禁'}}</span><small v-if="user.status!==1&&user.banReason" class="ban-reason">{{user.banReason}}</small></td><td>{{formatDate(user.lastLoginAt)}}</td><td>{{formatDate(user.createdAt)}}</td><td><div class="row-actions"><button v-if="user.status===1" type="button" :disabled="user.id===currentUserId" @click="openBan(user)">封禁</button><button v-else type="button" @click="enableUser(user)">解封</button><button type="button" @click="revokeSessions(user)">退出设备</button></div></td></tr><tr v-if="!users.length"><td colspan="6" class="empty-cell">没有符合条件的用户</td></tr></tbody></table></div>
      </section>

      <section v-else-if="tab==='feedback'" class="admin-section">
        <div class="section-toolbar"><div><h2>问题反馈</h2><p>查看用户截图、处理进度，并将回复发送到用户通知。</p></div><div class="toolbar-filters compact"><select v-model="feedbackFilters.status" class="input" @change="loadFeedback"><option value="">全部状态</option><option value="OPEN">待处理</option><option value="PROCESSING">处理中</option><option value="RESOLVED">已解决</option><option value="CLOSED">已关闭</option></select><select v-model="feedbackFilters.type" class="input" @change="loadFeedback"><option value="">全部类型</option><option value="BUG">功能异常</option><option value="UI">页面显示</option><option value="SUGGESTION">改进建议</option><option value="OTHER">其他问题</option></select></div></div>
        <div class="feedback-admin-list"><article v-for="item in feedback" :key="item.id"><header><div><strong>{{feedbackType(item.type)}} #{{item.id}}</strong><span>@{{item.username}} · {{formatDate(item.createdAt)}}</span></div><em :class="`feedback-${item.status.toLowerCase()}`">{{feedbackStatus(item.status)}}</em></header><p>{{item.description}}</p><div v-if="item.images?.length" class="admin-feedback-images"><a v-for="image in item.images" :key="image.id" :href="image.fileUrl" target="_blank" rel="noopener"><img :src="image.fileUrl" alt="用户反馈截图"/></a></div><blockquote v-if="item.adminReply"><strong>当前回复</strong>{{item.adminReply}}</blockquote><footer><span>{{item.documentTitle?`关联文档：${item.documentTitle}`:'未关联文档'}}</span><button class="btn btn-primary btn-sm" type="button" @click="openFeedbackHandle(item)">处理反馈</button></footer></article><div v-if="!feedback.length" class="empty-panel">暂无反馈记录</div></div>
      </section>

      <section v-else-if="tab==='notifications'" class="admin-section">
        <div class="section-toolbar"><div><h2>发送系统提示</h2><p>提示会显示在接收用户的页面上方，用户关闭后转为已读。</p></div></div>
        <form class="notification-compose" @submit.prevent="sendNotification">
          <fieldset><legend>发送范围</legend><div class="audience-options"><label :class="{active:notificationForm.targetType==='ALL'}"><input v-model="notificationForm.targetType" type="radio" value="ALL"/><Users :size="18"/><span><strong>全部用户</strong><small>发送给当前全部账号</small></span></label><label :class="{active:notificationForm.targetType==='USER'}"><input v-model="notificationForm.targetType" type="radio" value="USER"/><UserRound :size="18"/><span><strong>指定用户</strong><small>按用户名准确发送</small></span></label><label :class="{active:notificationForm.targetType==='REGISTERED_AT'}"><input v-model="notificationForm.targetType" type="radio" value="REGISTERED_AT"/><CalendarRange :size="18"/><span><strong>按注册时间</strong><small>开始、结束时间可单独填写</small></span></label></div></fieldset>
          <label v-if="notificationForm.targetType==='USER'">接收人用户名<input v-model.trim="notificationForm.username" class="input" maxlength="50" placeholder="请输入完整用户名" required/></label>
          <div v-if="notificationForm.targetType==='REGISTERED_AT'" class="form-columns"><label>注册开始时间（可选）<input v-model="notificationForm.registeredFrom" class="input" type="datetime-local"/></label><label>注册结束时间（可选）<input v-model="notificationForm.registeredTo" class="input" type="datetime-local"/></label></div>
          <label>提示内容<textarea v-model="notificationForm.content" class="input" rows="7" maxlength="500" placeholder="请输入用户能够直接理解的提示内容" required/></label>
          <div class="notification-compose-footer"><span>{{notificationForm.content.trim().length}} / 500 字</span><button class="btn btn-primary" type="submit" :disabled="notificationSending"><Send :size="16"/>{{notificationSending?'发送中...':'发送提示'}}</button></div>
        </form>
      </section>

      <section v-else-if="tab==='templates'" class="admin-section">
        <div class="section-toolbar"><div><h2>系统模板</h2><p>系统模板会出现在所有用户的“从模板创建”列表中。</p></div><button class="btn btn-primary" type="button" @click="openTemplate()"><Plus :size="16"/>新建系统模板</button></div>
        <div class="data-table-wrap"><table class="data-table"><thead><tr><th>名称</th><th>分类</th><th>格式</th><th>说明</th><th>更新时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in templates" :key="item.id"><td><strong>{{item.name}}</strong></td><td>{{item.category||'未分类'}}</td><td>{{item.contentFormat==='HTML'?'富文本':'Markdown'}}</td><td>{{item.description||'暂无说明'}}</td><td>{{formatDate(item.updatedAt)}}</td><td><div class="row-actions"><button type="button" @click="openTemplate(item)">编辑</button><button class="danger-text" type="button" @click="removeTemplate(item)">删除</button></div></td></tr><tr v-if="!templates.length"><td colspan="6" class="empty-cell">暂无系统模板</td></tr></tbody></table></div>
      </section>

      <section v-else-if="tab==='audit'" class="admin-section">
        <div class="section-toolbar"><div><h2>操作日志</h2><p>记录管理操作与项目原有的重要业务操作。</p></div><div class="toolbar-filters compact"><input v-model.trim="logAction" class="input" placeholder="按操作类型筛选" @keydown.enter="loadLogs"/><button class="btn btn-primary" type="button" @click="loadLogs">查询</button></div></div>
        <div class="data-table-wrap"><table class="data-table"><thead><tr><th>时间</th><th>操作人</th><th>操作类型</th><th>文档 ID</th><th>详情</th></tr></thead><tbody><tr v-for="item in logs" :key="item.id"><td>{{formatDate(item.createdAt)}}</td><td>{{item.username||`用户 ${item.userId}`}}</td><td><code>{{item.action}}</code></td><td>{{item.docId||'-'}}</td><td>{{item.detail||'-'}}</td></tr><tr v-if="!logs.length"><td colspan="5" class="empty-cell">暂无日志</td></tr></tbody></table></div>
      </section>

      <section v-else class="admin-section">
        <div class="section-toolbar"><div><h2>系统状态</h2><p>仅展示运行和存储统计，不提供绕过权限查看文档正文的入口。</p></div></div>
        <div class="system-grid"><article><Trash2 :size="20"/><div><strong>{{systemStatus.trashRetentionDays||30}} 天</strong><span>回收站保留期限</span></div></article><article><UploadCloud :size="20"/><div><strong>{{systemStatus.pendingUploads||0}}</strong><span>未完成分片上传</span></div></article><article><Paperclip :size="20"/><div><strong>{{systemStatus.attachments||0}}</strong><span>文档附件</span></div></article><article><HardDrive :size="20"/><div><strong>{{formatBytes(systemStatus.attachmentBytes||0)}}</strong><span>附件占用空间</span></div></article><article><Images :size="20"/><div><strong>{{systemStatus.feedbackImages||0}}</strong><span>反馈图片</span></div></article><article><DatabaseBackup :size="20"/><div><strong>{{systemStatus.crdtCheckpoints||0}}</strong><span>当前协作恢复点</span></div></article><article><History :size="20"/><div><strong>{{systemStatus.crdtCheckpointHistory||0}}</strong><span>历史协作恢复点</span></div></article><article><GitMerge :size="20"/><div><strong>{{systemStatus.crdtUpdates||0}}</strong><span>待整理协作更新</span></div></article></div>
      </section>
    </main>

    <div v-if="banDialog.open" class="modal-backdrop" @click.self="banDialog.open=false"><form class="modal admin-modal" @submit.prevent="submitBan"><header><h2>封禁用户</h2><button class="btn btn-icon btn-ghost" type="button" @click="banDialog.open=false"><X :size="18"/></button></header><p>封禁 <strong>{{banDialog.user?.username}}</strong> 后，其全部设备会立即退出。</p><label>封禁原因<textarea v-model.trim="banDialog.reason" class="input" rows="4" maxlength="500" required/></label><label>自动解封时间（可选）<input v-model="banDialog.expiresAt" class="input" type="datetime-local"/></label><footer><button class="btn btn-secondary" type="button" @click="banDialog.open=false">取消</button><button class="btn btn-danger" type="submit" :disabled="banDialog.saving">{{banDialog.saving?'处理中...':'确认封禁'}}</button></footer></form></div>
    <div v-if="feedbackDialog.open" class="modal-backdrop" @click.self="feedbackDialog.open=false"><form class="modal admin-modal" @submit.prevent="submitFeedbackHandle"><header><h2>处理反馈 #{{feedbackDialog.item?.id}}</h2><button class="btn btn-icon btn-ghost" type="button" @click="feedbackDialog.open=false"><X :size="18"/></button></header><label>处理状态<select v-model="feedbackDialog.status" class="input"><option value="OPEN">待处理</option><option value="PROCESSING">处理中</option><option value="RESOLVED">已解决</option><option value="CLOSED">已关闭</option></select></label><label>回复用户<textarea v-model.trim="feedbackDialog.reply" class="input" rows="6" maxlength="2000" placeholder="说明处理结果或需要用户补充的信息"/></label><footer><button class="btn btn-secondary" type="button" @click="feedbackDialog.open=false">取消</button><button class="btn btn-primary" type="submit" :disabled="feedbackDialog.saving">保存并通知用户</button></footer></form></div>
    <div v-if="templateDialog.open" class="modal-backdrop" @click.self="templateDialog.open=false"><form class="modal admin-modal template-modal" @submit.prevent="saveTemplate"><header><h2>{{templateDialog.id?'编辑系统模板':'新建系统模板'}}</h2><button class="btn btn-icon btn-ghost" type="button" @click="templateDialog.open=false"><X :size="18"/></button></header><label>模板名称<input v-model.trim="templateDialog.name" class="input" maxlength="100" required/></label><div class="form-columns"><label>分类<input v-model.trim="templateDialog.category" class="input" maxlength="100"/></label><label>内容格式<select v-model="templateDialog.contentFormat" class="input"><option value="MARKDOWN">Markdown</option><option value="HTML">富文本 HTML</option></select></label></div><label>模板说明<input v-model.trim="templateDialog.description" class="input" maxlength="500"/></label><label>模板内容<textarea v-model="templateDialog.content" class="input code-input" rows="12"/></label><footer><button class="btn btn-secondary" type="button" @click="templateDialog.open=false">取消</button><button class="btn btn-primary" type="submit" :disabled="templateDialog.saving">保存模板</button></footer></form></div>
  </div>
</template>

<script setup>
import { computed, markRaw, onMounted, reactive, ref } from 'vue'
import { BarChart3, CalendarRange, DatabaseBackup, FileText, GitMerge, HardDrive, History, Images, LayoutTemplate, ListChecks, Megaphone, MessageSquareWarning, Paperclip, Plus, RefreshCw, ScrollText, Search, Send, Settings, Trash2, UploadCloud, UserRound, Users, X } from 'lucide-vue-next'
import { adminApi } from '../api'
import { useUserStore } from '../store'
import { confirmDialog } from '../utils/dialog'
import { error, success } from '../utils/toast'
import { buildAdminNotificationPayload, describeAdminNotificationTarget } from '../utils/adminNotification'

const userStore=useUserStore(),currentUserId=computed(()=>userStore.user?.id)
const tabs=[{key:'overview',label:'总览',icon:markRaw(BarChart3)},{key:'users',label:'用户',icon:markRaw(Users)},{key:'feedback',label:'反馈',icon:markRaw(MessageSquareWarning)},{key:'notifications',label:'提示',icon:markRaw(Megaphone)},{key:'templates',label:'模板',icon:markRaw(LayoutTemplate)},{key:'audit',label:'日志',icon:markRaw(ScrollText)},{key:'system',label:'系统状态',icon:markRaw(Settings)}]
const overviewItems=[{key:'users',label:'用户总数',icon:markRaw(UserRound)},{key:'disabledUsers',label:'已封禁用户',icon:markRaw(Users)},{key:'documents',label:'正常文档',icon:markRaw(FileText)},{key:'trashDocuments',label:'回收站文档',icon:markRaw(Trash2)},{key:'openFeedback',label:'待处理反馈',icon:markRaw(ListChecks)},{key:'activeSessions',label:'有效登录设备',icon:markRaw(HardDrive)},{key:'attachments',label:'文档附件',icon:markRaw(Paperclip)},{key:'attachmentBytes',label:'附件占用',icon:markRaw(DatabaseBackup),bytes:true}]
const tab=ref('overview'),loading=ref(false),overview=reactive({}),users=ref([]),feedback=ref([]),templates=ref([]),logs=ref([]),systemStatus=reactive({}),logAction=ref('')
const userFilters=reactive({q:'',status:'',role:''}),feedbackFilters=reactive({status:'',type:''})
const notificationForm=reactive({targetType:'ALL',username:'',registeredFrom:'',registeredTo:'',content:''}),notificationSending=ref(false)
const banDialog=reactive({open:false,user:null,reason:'',expiresAt:'',saving:false}),feedbackDialog=reactive({open:false,item:null,status:'OPEN',reply:'',saving:false}),templateDialog=reactive({open:false,id:null,name:'',category:'',description:'',contentFormat:'MARKDOWN',content:'',saving:false})
onMounted(loadCurrent)
async function selectTab(value){tab.value=value;await loadCurrent()}
async function loadCurrent(){loading.value=true;try{if(tab.value==='overview'){const r=await adminApi.overview();Object.assign(overview,r.data||{})}if(tab.value==='users')await loadUsers();if(tab.value==='feedback')await loadFeedback();if(tab.value==='templates')await loadTemplates();if(tab.value==='audit')await loadLogs();if(tab.value==='system'){const r=await adminApi.systemStatus();Object.assign(systemStatus,r.data||{})}}catch(exception){error(exception.message||'管理数据加载失败')}finally{loading.value=false}}
async function loadUsers(){const r=await adminApi.users({q:userFilters.q||undefined,status:userFilters.status===''?undefined:Number(userFilters.status),role:userFilters.role||undefined});users.value=r.data||[]}
async function loadFeedback(){const r=await adminApi.feedback({status:feedbackFilters.status||undefined,type:feedbackFilters.type||undefined});feedback.value=r.data||[]}
async function loadTemplates(){const r=await adminApi.templates();templates.value=r.data||[]}
async function loadLogs(){const r=await adminApi.logs(logAction.value);logs.value=r.data||[]}
async function sendNotification(){
  let payload
  try{payload=buildAdminNotificationPayload(notificationForm)}catch(exception){error(exception.message);return}
  const target=describeAdminNotificationTarget(payload)
  if(!(await confirmDialog(`确定向${target}发送这条提示吗？`,{title:'确认发送系统提示',confirmText:'确认发送'})))return
  notificationSending.value=true
  try{const response=await adminApi.sendNotification(payload);success(`提示已发送给 ${response.data?.sentCount||0} 位用户`);notificationForm.content=''}
  catch(exception){error(exception.message||'系统提示发送失败')}
  finally{notificationSending.value=false}
}
function openBan(user){Object.assign(banDialog,{open:true,user,reason:'',expiresAt:'',saving:false})}
async function submitBan(){banDialog.saving=true;try{await adminApi.setUserStatus(banDialog.user.id,{enabled:false,reason:banDialog.reason,expiresAt:banDialog.expiresAt||null});success('用户已封禁，全部登录设备已退出');banDialog.open=false;await loadUsers()}catch(exception){error(exception.message||'封禁用户失败')}finally{banDialog.saving=false}}
async function enableUser(user){if(!(await confirmDialog(`确定解除用户“${user.username}”的封禁吗？`,{title:'解除封禁',confirmText:'解除'})))return;try{await adminApi.setUserStatus(user.id,{enabled:true});success('用户已恢复正常');await loadUsers()}catch(exception){error(exception.message||'解除封禁失败')}}
async function changeRole(user,role){if(!(await confirmDialog(`将“${user.username}”的系统角色改为${role==='ADMIN'?'管理员':'普通用户'}？`,{title:'修改系统角色',confirmText:'确认修改'}))){await loadUsers();return}try{await adminApi.setUserRole(user.id,role);success('系统角色已更新');await loadUsers()}catch(exception){error(exception.message||'角色修改失败');await loadUsers()}}
async function revokeSessions(user){if(!(await confirmDialog(`让“${user.username}”的所有设备退出登录？`,{title:'强制退出设备',confirmText:'全部退出',danger:true})))return;try{const r=await adminApi.revokeSessions(user.id);success(`已退出 ${r.data?.count||0} 个登录设备`)}catch(exception){error(exception.message||'设备退出失败')}}
function openFeedbackHandle(item){Object.assign(feedbackDialog,{open:true,item,status:item.status,reply:item.adminReply||'',saving:false})}
async function submitFeedbackHandle(){feedbackDialog.saving=true;try{const r=await adminApi.handleFeedback(feedbackDialog.item.id,{status:feedbackDialog.status,adminReply:feedbackDialog.reply});const index=feedback.value.findIndex(item=>item.id===r.data.id);if(index>=0)feedback.value[index]=r.data;feedbackDialog.open=false;success('反馈处理结果已保存并通知用户')}catch(exception){error(exception.message||'反馈处理失败')}finally{feedbackDialog.saving=false}}
function openTemplate(item=null){Object.assign(templateDialog,{open:true,id:item?.id||null,name:item?.name||'',category:item?.category||'',description:item?.description||'',contentFormat:item?.contentFormat||'MARKDOWN',content:item?.content||'',saving:false})}
async function saveTemplate(){templateDialog.saving=true;try{const payload={name:templateDialog.name,category:templateDialog.category||null,description:templateDialog.description||null,contentFormat:templateDialog.contentFormat,content:templateDialog.content};if(templateDialog.id)await adminApi.updateTemplate(templateDialog.id,payload);else await adminApi.createTemplate(payload);templateDialog.open=false;success('系统模板已保存');await loadTemplates()}catch(exception){error(exception.message||'系统模板保存失败')}finally{templateDialog.saving=false}}
async function removeTemplate(item){if(!(await confirmDialog(`删除系统模板“${item.name}”？`,{title:'删除系统模板',confirmText:'删除',danger:true})))return;try{await adminApi.removeTemplate(item.id);success('系统模板已删除');await loadTemplates()}catch(exception){error(exception.message||'模板删除失败')}}
const feedbackType=value=>({BUG:'功能异常',UI:'页面显示',SUGGESTION:'改进建议',OTHER:'其他问题'}[value]||value),feedbackStatus=value=>({OPEN:'待处理',PROCESSING:'处理中',RESOLVED:'已解决',CLOSED:'已关闭'}[value]||value)
const formatDate=value=>value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'暂无记录',formatNumber=(value,bytes)=>bytes?formatBytes(value):Number(value).toLocaleString('zh-CN'),formatBytes=value=>{const size=Number(value)||0;if(size<1024)return`${size} B`;if(size<1024**2)return`${(size/1024).toFixed(1)} KB`;if(size<1024**3)return`${(size/1024**2).toFixed(1)} MB`;return`${(size/1024**3).toFixed(2)} GB`}
</script>

<style scoped>
